from collections import deque

# Grafo como lista de adyacencia
graph = {0: [1, 2], 1: [3], 2: [3], 3: [4], 4: []}

# BFS
def bfs(start):
    visited = []
    queue = deque([start])
    while queue:
        node = queue.popleft()
        if node not in visited:
            visited.append(node)
            queue.extend(graph[node])
    return visited

# DFS
def dfs(node, visited=None):
    if visited is None:
        visited = []
    visited.append(node)
    for neighbor in graph[node]:
        if neighbor not in visited:
            dfs(neighbor, visited)
    return visited

print(bfs(0))   # [0, 1, 2, 3, 4]
print(dfs(0))   # [0, 1, 3, 2, 4]
